use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

const MODERATE_SYSTEM: &str =
    "You are a content moderation classifier. Reply with exactly one word: OK, VIOLATION, or ESCALATE.";

fn hex_digit(n: u8) -> char {
    b"0123456789ABCDEF"[n as usize] as char
}

/// Percent-encode a string for use as a query-string value.
fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex_digit(b >> 4));
                out.push(hex_digit(b & 0x0F));
            }
        }
    }
    out
}

/// Fetch the enrichment record for the input. The record does not feed the
/// verdict, so the node's output is unchanged by it. A transport failure is a
/// value and is ignored; a refused host traps at the boundary.
fn enrich(text: &str) {
    let url = format!("{}{}", ENRICH_BASE, percent_encode(text));
    let _ = http_client::fetch(&url);
}

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        enrich(&query.question);

        let verdict = inference_llm::infer(MODERATE_SYSTEM, &query.question, "moderate");

        // Take the first alphabetic word of the reply, uppercased. Anything
        // other than OK or VIOLATION fails closed to human escalation.
        let normalized = verdict.trim().to_ascii_uppercase();
        let word = normalized
            .split(|c: char| !c.is_ascii_alphabetic())
            .next()
            .unwrap_or("");

        match word {
            "OK" => ModerationResult::Ok(ModeratedQuery { query }),
            "VIOLATION" => ModerationResult::Violation(PolicyViolation {
                reason: "content policy violation".to_string(),
            }),
            _ => ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "moderation requires human review".to_string(),
            }),
        }
    }
}

export!(Node);
```

